import{_ as a,o as e,c as n,a2 as s}from"./chunks/framework.XXezeKOl.js";const g=JSON.parse('{"title":"Agent、Chatbot 与 Workflow 的区别","description":"从控制流归属、可预测性、成本三个维度区分 Chatbot、Workflow 与 Agent，并给出选型决策方法。","frontmatter":{"title":"Agent、Chatbot 与 Workflow 的区别","description":"从控制流归属、可预测性、成本三个维度区分 Chatbot、Workflow 与 Agent，并给出选型决策方法。"},"headers":[],"relativePath":"guide/00-intro/agent-vs-workflow.md","filePath":"guide/00-intro/agent-vs-workflow.md","lastUpdated":null}'),l={name:"guide/00-intro/agent-vs-workflow.md"};function r(o,t,i,d,p,h){return e(),n("div",null,[...t[0]||(t[0]=[s(`<h1 id="agent、chatbot-与-workflow-的区别" tabindex="-1">Agent、Chatbot 与 Workflow 的区别 <a class="header-anchor" href="#agent、chatbot-与-workflow-的区别" aria-label="Permalink to &quot;Agent、Chatbot 与 Workflow 的区别&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">学习目标</p><ul><li>用「谁决定下一步」这一个问题区分 Chatbot、Workflow、Agent</li><li>了解五种常见 Workflow 模式，以及它们和 Agent 的关系</li><li>掌握一套选型决策方法：什么时候不该用 Agent</li><li>理解实际系统往往是三者的混合</li></ul></div><h2 id="三种形态一张表" tabindex="-1">三种形态一张表 <a class="header-anchor" href="#三种形态一张表" aria-label="Permalink to &quot;三种形态一张表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>Chatbot</th><th>Workflow</th><th>Agent</th></tr></thead><tbody><tr><td>谁决定下一步</td><td>用户（每轮由人推进）</td><td>开发者写好的代码</td><td>模型自己</td></tr><tr><td>是否调用工具</td><td>通常没有或很少</td><td>有，在固定节点调用</td><td>有，由模型选择调用哪个、调几次</td></tr><tr><td>步骤数</td><td>一问一答</td><td>固定或有限分支</td><td>动态，事先不确定</td></tr><tr><td>可预测性</td><td>高</td><td>高</td><td>低</td></tr><tr><td>成本与延迟</td><td>低</td><td>中，可估算</td><td>高，波动大</td></tr><tr><td>调试难度</td><td>低</td><td>中</td><td>高，需要轨迹追踪</td></tr><tr><td>典型场景</td><td>客服问答、写作助手</td><td>文档抽取、报表生成、审批流</td><td>编程助手、深度研究、运维排障</td></tr></tbody></table><p>一句话记忆：<strong>Chatbot 是人在驾驶，Workflow 是轨道列车，Agent 是自动驾驶</strong>。</p><h2 id="chatbot-人推动每一步" tabindex="-1">Chatbot：人推动每一步 <a class="header-anchor" href="#chatbot-人推动每一步" aria-label="Permalink to &quot;Chatbot：人推动每一步&quot;">​</a></h2><p>Chatbot 的核心是多轮对话。模型每次只回答当前这一轮，下一步做什么由用户决定。</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户 ──▶ LLM ──▶ 回复 ──▶ 用户看完再提问 ──▶ LLM ──▶ ...</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>它可以很强大（长上下文、联网搜索、上传文件），但主动权始终在人手里。很多所谓「AI 助手」本质是 Chatbot，加了一两个工具也不改变这一点。</p><h2 id="workflow-代码编排-llm" tabindex="-1">Workflow：代码编排 LLM <a class="header-anchor" href="#workflow-代码编排-llm" aria-label="Permalink to &quot;Workflow：代码编排 LLM&quot;">​</a></h2><p>Workflow 把任务拆成预先定义的步骤，LLM 是其中的若干节点。Anthropic 在《Building effective agents》里总结了几种常见模式：</p><table tabindex="0"><thead><tr><th>模式</th><th>结构</th><th>适用场景</th></tr></thead><tbody><tr><td>Prompt Chaining（链式）</td><td>A → B → C，上一步输出作为下一步输入，中间可插入校验</td><td>先写大纲再写正文；先翻译再润色</td></tr><tr><td>Routing（路由）</td><td>分类器决定走哪条分支</td><td>客服问题分类后交给不同处理流程</td></tr><tr><td>Parallelization（并行）</td><td>同一任务拆成多份并行，或多次投票</td><td>长文档分段摘要；多次审查取多数</td></tr><tr><td>Orchestrator-Workers（编排者-工人）</td><td>一个 LLM 动态拆解子任务，分发给多个 LLM 执行</td><td>修改涉及多个文件的代码</td></tr><tr><td>Evaluator-Optimizer（评估-优化）</td><td>生成 → 评估 → 根据反馈改进，循环若干轮</td><td>翻译润色、代码按测试修复</td></tr></tbody></table><p>以「合同信息抽取」为例，一个典型 Workflow：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PDF ──▶ 解析文本 ──▶ LLM 抽取字段 ──▶ Schema 校验 ──┬─ 通过 ──▶ 入库</span></span>
<span class="line"><span>                                                  └─ 失败 ──▶ 带错误重试（最多 2 次）──▶ 人工审核</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>每一步做什么、失败怎么办，全部写在代码里。这让它<strong>可测试、可估算成本、出了问题容易定位</strong>。</p><p>注意后两种模式已经让 LLM 掌握了部分控制权，它们处在 Workflow 和 Agent 之间。这正说明两者是连续的光谱，而不是二选一。</p><h2 id="agent-模型掌握控制流" tabindex="-1">Agent：模型掌握控制流 <a class="header-anchor" href="#agent-模型掌握控制流" aria-label="Permalink to &quot;Agent：模型掌握控制流&quot;">​</a></h2><p>Agent 把「下一步做什么」交给模型。开发者提供的是工具、目标、约束和终止条件，而不是步骤。</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>目标 ──▶ ┌─▶ LLM 决策 ──▶ 调用工具 ──▶ 观察结果 ─┐</span></span>
<span class="line"><span>         └──────────────────────────────────────┘ ──▶ 完成 / 达到上限</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>以「修复一个线上 Bug」为例：Agent 可能先搜日志，发现异常后读相关代码，再跑测试复现，修改代码，再跑测试。这个路径事先无法写死，因为每一步都依赖上一步的发现。这正是 Agent 的价值所在。</p><p>代价同样明显：同一个任务跑两次，步骤可能不同；某次可能多花 3 倍 Token；模型可能走进死胡同。所以 Agent 必须配套评估、追踪、预算控制，这些内容在 <a href="/guide/14-evaluation/why-evals">14 评估与可观测性</a> 和 <a href="/guide/15-production/permissions-hitl">15 安全与生产化</a> 里展开。</p><h2 id="选型-从最简单的方案开始" tabindex="-1">选型：从最简单的方案开始 <a class="header-anchor" href="#选型-从最简单的方案开始" aria-label="Permalink to &quot;选型：从最简单的方案开始&quot;">​</a></h2><p>一个实用的决策顺序：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 一次 LLM 调用（加好的提示词、检索）能解决吗？  ── 能 ──▶ 就用它</span></span>
<span class="line"><span>                │ 不能</span></span>
<span class="line"><span>2. 步骤能事先列清楚吗？                         ── 能 ──▶ Workflow</span></span>
<span class="line"><span>                │ 不能，路径依赖中间结果</span></span>
<span class="line"><span>3. 错误代价可控吗？有评估手段吗？                ── 否 ──▶ 先补评估 / 加人工审核</span></span>
<span class="line"><span>                │ 是</span></span>
<span class="line"><span>4. 用单 Agent，设好工具、步数和预算上限</span></span>
<span class="line"><span>                │ 单 Agent 上下文装不下，或职责差异很大</span></span>
<span class="line"><span>5. 考虑多 Agent</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><p>判断「步骤能否事先列清楚」时，可以问自己：<strong>如果让一个新同事做，我能写一份固定 SOP 吗？</strong> 能写，就优先 Workflow；SOP 里充满「视情况而定」，Agent 才有意义。</p><h2 id="现实系统是混合的" tabindex="-1">现实系统是混合的 <a class="header-anchor" href="#现实系统是混合的" aria-label="Permalink to &quot;现实系统是混合的&quot;">​</a></h2><p>生产系统很少是纯粹的某一种：</p><ul><li>一个客服系统整体是 Chatbot，但「退款」意图会路由到一个固定 Workflow，「复杂故障排查」再交给一个 Agent。</li><li>一个 Agent 的某个工具内部，可能就是一个确定性的 Workflow（例如「生成并校验报表」）。</li><li>LangGraph 这类框架的思路正是把 Workflow 的确定性和 Agent 的灵活性组合在一张图里，详见 <a href="/guide/11-frameworks/langgraph">LangGraph</a>。</li></ul><p>把它们当作工具箱里的三种工具，而不是三个互斥的阵营。</p><h2 id="常见坑" tabindex="-1">常见坑 <a class="header-anchor" href="#常见坑" aria-label="Permalink to &quot;常见坑&quot;">​</a></h2><ul><li><strong>为了「Agent」而 Agent</strong>。用 Agent 实现一个固定三步流程，结果更慢、更贵、更不稳定。</li><li><strong>把 Workflow 写成巨大的 if-else 来模拟灵活性</strong>。分支爆炸时，说明这部分可能该交给模型决策。</li><li><strong>只在 Demo 上比较</strong>。Agent 在演示里常常很惊艳，但要用几十上百条真实样例评估成功率和成本后再决定。</li><li><strong>忽略混合方案</strong>。不必整个系统都是 Agent，只在真正需要动态决策的环节用 Agent。</li></ul><h2 id="小测" tabindex="-1">小测 <a class="header-anchor" href="#小测" aria-label="Permalink to &quot;小测&quot;">​</a></h2><p><strong>1. 「每天早上抓取 10 个固定网站的新闻，逐条摘要后汇总成日报发邮件」，适合用 Agent 还是 Workflow？</strong></p><details class="details custom-block"><summary>查看答案</summary><p>Workflow。步骤固定（抓取 → 摘要 → 汇总 → 发送），可以并行摘要（Parallelization 模式）。用 Agent 只会增加成本和不确定性。</p></details><p><strong>2. Orchestrator-Workers 模式和 Agent 有什么相同和不同？</strong></p><details class="details custom-block"><summary>查看答案</summary><p>相同点：都由 LLM 动态决定任务如何拆解。不同点：Orchestrator-Workers 的整体结构（先拆解、再分发、再汇总）是固定的，通常一次拆解就结束；Agent 则在开放循环中持续根据观察结果决定下一步，步数和路径都不固定。</p></details><p><strong>3. 你的 Agent 在演示中效果很好，上线前最应该补哪件事？</strong></p><details class="details custom-block"><summary>查看答案</summary><p>建立评估集，用一批真实任务批量运行，统计成功率、平均步数、Token 成本和失败类型。同时加上步数、预算上限和轨迹追踪。没有评估就无法知道改动是变好还是变坏。</p></details><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li><a href="https://www.anthropic.com/engineering/building-effective-agents" target="_blank" rel="noreferrer">Anthropic: Building effective agents</a></li><li>本站：<a href="/guide/06-agent-loop/plan-execute">Plan-and-Execute</a>、<a href="/guide/12-multi-agent/patterns">编排模式：主从、流水线、交接、辩论</a>、<a href="/guide/14-evaluation/why-evals">为什么评估是第一优先级</a></li></ul>`,40)])])}const u=a(l,[["render",r]]);export{g as __pageData,u as default};
